import sys, json
for line in sys.stdin:
    i, m = line.split('|',1)
    m = json.loads(m)
    print('=== exp', i)
    def show(d, pre=''):
        for k,v in d.items():
            if isinstance(v, dict):
                show(v, pre+k+'.')
            elif isinstance(v,(int,float,str,bool)) or v is None:
                print(pre+k, '=', v)
    show(m)
